  // ---- Event delegation for todo list ----
  // Intercept mousedown on .toggle checkboxes so the browser does NOT natively toggle
  // the checked property.  In a real browser, a native toggle + our handler's DOM
  // mutation on the same click event creates two mutations that Cypress detects as a
  // "page update", breaking a chained command.  We prevent the native toggle and
  // manage the checked property entirely in our toggleTodo handler.
  todoList.addEventListener('mousedown', function (e) {
    if (e.target.classList.contains('toggle')) {
      e.preventDefault();
    }
  });

  todoList.addEventListener('click', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var id = Number(li.dataset.id);

    // Toggle checkbox — native toggle was prevented in mousedown, so we must
    // explicitly set .checked to match the data model.
    if (e.target.classList.contains('toggle')) {
      toggleTodo(id);
    }

    // Destroy button
    if (e.target.classList.contains('destroy')) {
      destroyTodo(id);
    }
  });

  // Double-click to edit
  todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;
    enterEditMode(li);
  });

  // Edit input events (delegated)
  todoList.addEventListener('focusout', function (e) {
    if (!e.target.classList.contains('edit')) return;
    var li = e.target.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;
    submitEdit(li);
  });

  todoList.addEventListener('keypress', function (e) {
    if (e.keyCode !== ENTER_KEY) return;
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;
    submitEdit(li);
  });

  todoList.addEventListener('keydown', function (e) {
    if (e.keyCode !== ESCAPE_KEY) return;
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;
    cancelEdit(li);
  });

  // ---- Helper: update non-list UI without rebuilding todo-list ----
  function refreshControls() {
    var allCompleted = todoData.length > 0 && todoData.every(function (t) { return t.completed; });
    toggleAllCheckbox.checked = allCompleted;

    var hasTodos = todoData.length > 0;
    mainEl.style.display = hasTodos ? 'block' : 'none';
